import fs from 'node:fs';
import path from 'node:path';
const root = path.resolve(import.meta.dirname, '../..');
const read = (file) => fs.readFileSync(path.join(root, file), 'utf8');
let failed = 0;
const check = (label, condition) => { if (condition) console.log(`PASS: ${label}`); else { failed += 1; console.error(`FAIL: ${label}`); } };
const schema = read('prisma/schema.prisma');
const migration = read('prisma/migrations/20260825050000_system_administration_governance/migration.sql');
const users = read('src/users/users.service.ts');
const controller = read('src/system-administration/system-administration.controller.ts');
const service = read('src/system-administration/system-administration.service.ts');
const healthController = read('src/health/health.controller.ts');
const healthService = read('src/health/health.service.ts');
const scheduler = read('src/notifications/notification-scheduler.service.ts');
const frontend = read('../ctic-frontend/app/components/SystemGovernancePanel.tsx');
const p09 = read('scripts/tests/run-p09-real-e2e.cjs');
check('Migration 28 is additive and adds audit before/after metadata only', /details_json/.test(schema) && /ALTER TABLE \[audit_logs\][\s\S]*ADD \[details_json\]/.test(migration) && !/DROP|DELETE|TRUNCATE/i.test(migration));
check('System Administration is ADMIN-only server-side', /@Roles\('ADMIN'\)/.test(controller) && !/@Roles\([^)]*CUSTOMER/.test(controller));
check('System Administration projection exposes no mutation endpoints', !/@(Post|Patch|Delete|Put)\(/.test(controller));
check('Runtime role and permission designers are locked as code-governed', (users.match(/system invariant được quản trị trong code/g) ?? []).length >= 3);
check('Internal administration blocks CUSTOMER shortcut', /CUSTOMER chỉ được cấp qua quy trình customer access Phase 3\.2B/.test(users));
check('Last active ADMIN changes use SERIALIZABLE safety', /ADMIN hoạt động cuối cùng/.test(users) && /TransactionIsolationLevel\.Serializable/.test(users));
check('Account and role changes revoke existing sessions', (users.match(/user_sessions\.updateMany/g) ?? []).length >= 3);
check('Security-sensitive user changes write before/after metadata', /details_json: JSON\.stringify\([\s\S]*before:[\s\S]*after:/.test(users));
check('Public readiness is projected through the minimal response', /getPublicReadiness/.test(healthController) && /PublicReadinessResponse/.test(healthService));
check('Detailed health omits secrets and raw storage paths', /secrets_exposed: false/.test(service) && /raw_paths_exposed: false/.test(service) && !/rootDirectory|documentsDirectory/.test(service));
check('Scheduler exposes only safe lifecycle state and retains shutdown wait', /getStatus\(\)/.test(scheduler) && /Promise\.all\(Array\.from\(this\.inFlight\)\)/.test(scheduler));
check('Customer access projects the controlled direct/request authority and imports remain Phase 7 scoped', /mutation_authority: 'CONTROLLED_DIRECT_OR_REQUEST_WORKFLOW'/.test(service) && /supported_scope_remains_phase_7: true/.test(service));
check('Audit explorer remains paginated and read-only', /api\.get<Page<AuditLog>>\(`\/audit-logs\?\$\{auditQuery\}`\)/.test(frontend) && /Nhật ký hệ thống chỉ đọc/.test(frontend));
check('Administration UI reuses Phase 7 configuration components', /MasterDataConfigurationPanel/.test(frontend) && /CertificationBodyCapabilitiesPanel/.test(frontend));
check('P09 contract includes migration 28 and Phase 9 real SQL suite', /20260825050000_system_administration_governance/.test(p09) && /system-administration-governance\.e2e-spec\.ts/.test(p09));
console.log(`\nPhase 9 system administration governance regression: ${15 - failed}/15 PASS`);
if (failed) process.exitCode = 1;
